public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    final byte[] data = schema.toByteArray(message, buffer);
    ProtobufOutput output = new ProtobufLinkedBufferOutput(buffer);
    output.writeUInt32NoTag(data.length);
    output.writeByteArrayNoTag(data);
    return output.getTotalBytesWritten();
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    final byte[] data = schema.toByteArray(message, buffer);
    final int size = data.length;
    final int headerSize = VarIntSize(size);
    final byte[] header = new byte[headerSize];
    VarInt.write(size, header, 0);
    out.write(header);
    out.write(data);
    return size;
}

