    // Calculate the day of the month for the re-formatted time bucket
    int compressedDay = ((day - 1) / dayStep) * dayStep + 1;

    // Edge case: if the compressed day exceeds the maximum days in the month, adjust it
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2 && ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))) {
