    float x = box.getX();
    float y = box.getY();
    float height = box.getHeight();

    Box2D leftBox = new Box2D(x, y, halfWidth, height);
    Box2D rightBox = new Box2D(x + halfWidth, y, halfWidth, height);

    return new Pair<>(leftBox, rightBox);
}

