    if (type == Character.class) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String strValue = (String) value;
            if (strValue.length() == 1) {
                return strValue.charAt(0);
            } else {
                throw new IllegalArgumentException("String length must be 1 to convert to Character");
            }
        } else if (value instanceof Number) {
            Number numValue = (Number) value;
            int intValue = numValue.intValue();
            if (intValue >= Character.MIN_VALUE && intValue <= Character.MAX_VALUE) {
                return (char) intValue;
            } else {
                throw new IllegalArgumentException("Number out of Character range");
            }
        } else {
            throw new IllegalArgumentException("Unsupported conversion to Character from " + value.getClass().getName());
        }
    }
    throw new IllegalArgumentException("Type conversion to " + type.getName() + " is not supported");
}

