protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    if (!edgeList.isEmpty()) {
        V currentVertex = graph.getEdgeSource(edgeList.get(0));
        vertexList.add(currentVertex);
        for (E edge : edgeList) {
            if (graph.getEdgeSource(edge).equals(currentVertex)) {
                currentVertex = graph.getEdgeTarget(edge);
            } else {
                currentVertex = graph.getEdgeSource(edge);
            }
            vertexList.add(currentVertex);
        }
    }
    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), vertexList, edgeList, 0);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<V> pathVertices = new ArrayList<>();
    if (tour.isEmpty()) {
        return new GraphPath<>(graph, null, pathVertices, 0.0);
    }

    // Start from an arbitrary vertex of the first edge
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    pathVertices.add(startVertex);

    Set<E> remainingEdges = new HashSet<>(tour);
    V currentVertex = startVertex;

    while (!remainingEdges.isEmpty()) {
        for (E edge : remainingEdges) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);

            if (source.equals(currentVertex) || target.equals(currentVertex)) {
                pathVertices.add(source.equals(currentVertex) ? target : source);
                currentVertex = pathVertices.get(pathVertices.size() - 1);
                remainingEdges.remove(edge);
                break;
            }
        }
    }

    double weight = 0.0;
    for (E edge : tour) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPath<>(graph, startVertex, pathVertices, weight);
}

