private String unescapeId(String input){
    if (input == null || input.length() < 2) {
        return input;
    }
    if (input.startsWith("\"") && input.endsWith("\"")) {
        return input.substring(1, input.length() - 1).replace("\\\"", "\"").replace("\\\\", "\\");
    }
    return input;
}

