    }
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");
    int pathIndex = pathParts.length - 1;

    for (String part : relativeParts) {
        if (part.equals("..")) {
            if (pathIndex > 0) { // Go up one directory, but not above the root
                pathIndex--;
            }
        } else if (!part.equals(".")) { // Ignore current directory marker
            pathParts[++pathIndex] = part;
        }
    }
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= pathIndex; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(pathParts[i]);
    }
    return result.toString();
}

