public int readTag() throws IOException {
    int firstByte = input.read();
    if (firstByte == -1) {
        return 0; // End of input
    }
    int tag = firstByte & 0x7F;
    int shift = 7;
    while ((firstByte & 0x80) != 0) {
        firstByte = input.read();
        if (firstByte == -1) {
            throw new InvalidProtocolBufferException("Truncated message");
        }
        tag |= (firstByte & 0x7F) << shift;
        shift += 7;
    }
    return tag;
}

